// Paginação completa com retry em 429
// DECISÃO: Code único para simplicidade; fetch disponível em Node 18+
const apiKey = 'driva_test_key_abc123xyz789';
const baseUrl = 'http://api:3000/people/v1/enrichments';
const limit = 50;
let page = 1;
let totalPages = 1;
const allData = [];

const now = new Date().toISOString();

do {
  let res = await fetch(`${baseUrl}?page=${page}&limit=${limit}`, {
    headers: { 'Authorization': `Bearer ${apiKey}` }
  });

  while (res.status === 429) {
    await new Promise(r => setTimeout(r, 2000));
    res = await fetch(`${baseUrl}?page=${page}&limit=${limit}`, {
      headers: { 'Authorization': `Bearer ${apiKey}` }
    });
  }

  const json = await res.json();
  totalPages = json.total_pages || 1;

  for (const item of json.data || []) {
    allData.push({
      json: {
        ...item,
        dw_ingested_at: now,
        dw_updated_at: now
      }
    });
  }
  page++;
} while (page <= totalPages);

return allData.length ? allData : [{ json: { count: 0 } }];
